#!/usr/bin/env python3
"""Build the MESHWEAVE POC report body (ReportLab)."""

from __future__ import annotations

import sys
from pathlib import Path

from reportlab.lib import colors
from reportlab.lib.enums import TA_JUSTIFY, TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import mm
from reportlab.platypus import (
    BaseDocTemplate,
    Frame,
    Image,
    KeepTogether,
    PageBreak,
    PageTemplate,
    Paragraph,
    Spacer,
    Table,
    TableStyle,
)

# ── Cascade palette (generated by pdf.py palette.cascade) ──
PAGE_BG = colors.HexColor("#f4f5f5")
SECTION_BG = colors.HexColor("#f1f2f2")
TABLE_STRIPE = colors.HexColor("#edeff0")
HEADER_FILL = colors.HexColor("#324650")
COVER_BLOCK = colors.HexColor("#4c6572")
BORDER = colors.HexColor("#b8c7ce")
ACCENT = colors.HexColor("#c85934")
TEXT_PRIMARY = colors.HexColor("#1d1f20")
TEXT_MUTED = colors.HexColor("#858b8e")
SEM_SUCCESS = colors.HexColor("#468d5e")
SEM_WARNING = colors.HexColor("#8d7749")
SEM_ERROR = colors.HexColor("#a8524a")

PAGE_W, PAGE_H = A4
MARGIN = 20 * mm
CONTENT_W = PAGE_W - 2 * MARGIN

styles = getSampleStyleSheet()

S = {}
S["body"] = ParagraphStyle(
    "body", parent=styles["BodyText"], fontName="Helvetica", fontSize=9.4,
    leading=14.2, textColor=TEXT_PRIMARY, alignment=TA_JUSTIFY, spaceAfter=6,
)
S["h1"] = ParagraphStyle(
    "h1", parent=styles["Heading1"], fontName="Helvetica-Bold", fontSize=17,
    leading=21, textColor=HEADER_FILL, spaceBefore=2, spaceAfter=9,
)
S["h2"] = ParagraphStyle(
    "h2", parent=styles["Heading2"], fontName="Helvetica-Bold", fontSize=11.6,
    leading=15, textColor=ACCENT, spaceBefore=13, spaceAfter=5,
)
S["kicker"] = ParagraphStyle(
    "kicker", fontName="Helvetica", fontSize=7.6, leading=9,
    textColor=TEXT_MUTED, spaceAfter=3,
)
S["bullet"] = ParagraphStyle(
    "bullet", parent=S["body"], leftIndent=11, bulletIndent=2, spaceAfter=3,
)
S["cell"] = ParagraphStyle(
    "cell", fontName="Helvetica", fontSize=8.1, leading=10.2, textColor=TEXT_PRIMARY,
)
S["cellb"] = ParagraphStyle(
    "cellb", fontName="Helvetica-Bold", fontSize=8.1, leading=10.2, textColor=colors.white,
)
S["caption"] = ParagraphStyle(
    "caption", fontName="Helvetica", fontSize=7.6, leading=9.6,
    textColor=TEXT_MUTED, spaceBefore=3, spaceAfter=10,
)


def P(text: str, st: str = "body") -> Paragraph:
    return Paragraph(text, S[st])


def bullet(text: str) -> Paragraph:
    return Paragraph(text, S["bullet"], bulletText="•")


def section(title: str) -> list:
    return [P(title.upper(), "h2")]


def table(rows: list[list[str]], widths: list[float], caption: str | None = None) -> list:
    """Build a table, wrapping every cell in a Paragraph so long text cannot overflow."""
    data = []
    for r, row in enumerate(rows):
        style = "cellb" if r == 0 else "cell"
        data.append([Paragraph(str(c), S[style]) for c in row])
    total = sum(widths)
    scaled = [CONTENT_W * (w / total) for w in widths]
    t = Table(data, colWidths=scaled, repeatRows=1, hAlign="CENTER")
    ts = [
        ("BACKGROUND", (0, 0), (-1, 0), HEADER_FILL),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("TOPPADDING", (0, 0), (-1, -1), 4),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
        ("LEFTPADDING", (0, 0), (-1, -1), 5),
        ("RIGHTPADDING", (0, 0), (-1, -1), 5),
        ("LINEBELOW", (0, 0), (-1, -1), 0.4, BORDER),
        ("BOX", (0, 0), (-1, -1), 0.5, BORDER),
    ]
    for i in range(1, len(data)):
        if i % 2 == 0:
            ts.append(("BACKGROUND", (0, i), (-1, i), TABLE_STRIPE))
    t.setStyle(TableStyle(ts))
    out = [Spacer(1, 3), t]
    if caption:
        out.append(P(caption, "caption"))
    return out


def callout(title: str, text: str, tone: str = "accent") -> Table:
    colour = {"accent": ACCENT, "good": SEM_SUCCESS, "warn": SEM_WARNING, "bad": SEM_ERROR}[tone]
    inner = [
        Paragraph(f'<font color="{colour.hexval()}"><b>{title}</b></font>', S["cell"]),
        Paragraph(text, S["cell"]),
    ]
    t = Table([[inner]], colWidths=[CONTENT_W])
    t.setStyle(
        TableStyle(
            [
                ("BACKGROUND", (0, 0), (-1, -1), SECTION_BG),
                ("LINEBEFORE", (0, 0), (0, -1), 2.4, colour),
                ("LEFTPADDING", (0, 0), (-1, -1), 9),
                ("RIGHTPADDING", (0, 0), (-1, -1), 9),
                ("TOPPADDING", (0, 0), (-1, -1), 7),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 7),
            ]
        )
    )
    return t


def build(path: str) -> None:
    doc = BaseDocTemplate(
        path, pagesize=A4,
        leftMargin=MARGIN, rightMargin=MARGIN, topMargin=MARGIN, bottomMargin=18 * mm,
        title="MESHWEAVE — Distributed AI Compute Fabric (POC)",
        author="MESHWEAVE", subject="Proof of concept technical report",
        creator="MESHWEAVE",
    )

    frame = Frame(MARGIN, 18 * mm, CONTENT_W, PAGE_H - MARGIN - 18 * mm, id="main")

    def footer(canvas, doc_):
        canvas.saveState()
        canvas.setFont("Helvetica", 7.2)
        canvas.setFillColor(TEXT_MUTED)
        canvas.drawString(MARGIN, 11 * mm, "MESHWEAVE — Many Machines. One Intelligence.")
        canvas.drawRightString(PAGE_W - MARGIN, 11 * mm, f"{doc_.page}")
        canvas.setStrokeColor(BORDER)
        canvas.setLineWidth(0.4)
        canvas.line(MARGIN, 14 * mm, PAGE_W - MARGIN, 14 * mm)
        canvas.restoreState()

    doc.addPageTemplates([PageTemplate(id="main", frames=[frame], onPage=footer)])

    story: list = []

    # ── 1. Executive summary ──────────────────────────────────────────────
    story += section("Executive summary")
    story.append(P(
        "MESHWEAVE investigated one question: can GPUs rented from different cloud "
        "providers, on different physical machines, be coordinated to execute one "
        "language model together? Three Vast.ai instances were acquired — an NVIDIA "
        "GTX 1660 Super, a Quadro RTX 4000 and an RTX 2070 Super, 22 GB of VRAM in "
        "total — and a distributed inference system was built, measured and compared "
        "against simpler alternatives."
    ))
    story.append(P(
        "The distributed system works. A 32-layer Mixture-of-Experts model was split "
        "across all three hosts, each loading only its own layers from local disk, with "
        "only 8 KiB activations crossing the network per token. Output matched the "
        "llama.cpp reference at cosine similarity 0.9999994."
    ))
    story.append(Spacer(1, 5))
    story.append(callout(
        "The measurement that matters",
        "Distributed execution over ~300 ms links is <b>not competitive</b> for "
        "inference on this fleet. A single machine running the same model with two "
        "layers offloaded to RAM achieved <b>58 tokens/second</b>. The three-host "
        "pipeline achieved <b>2.2 tokens/second</b>. CPU offload was 26× faster, and a "
        "single GPU holding a smaller model was ~200× faster.",
        "bad",
    ))
    story.append(Spacer(1, 4))
    story.append(P(
        "This report records the engineering, the measurements, and the conclusion. "
        "The negative result is the substance of the work: it is what a fleet of small, "
        "geographically separated GPUs can and cannot do."
    ))

    # ── 2. Hardware and topology ──────────────────────────────────────────
    story += section("Infrastructure")
    story += table(
        [
            ["Host", "GPU", "VRAM", "RAM", "Role in pipeline"],
            ["HOST-A", "GTX 1660 Super", "6,144 MiB", "62 GB", "embedding + layers 0-10"],
            ["HOST-B", "Quadro RTX 4000", "8,192 MiB", "15 GB", "layers 11-20"],
            ["HOST-C", "RTX 2070 Super", "8,192 MiB", "31 GB", "layers 21-31 + head"],
        ],
        [0.9, 1.5, 1.0, 0.7, 2.2],
        "Three independently rented Vast.ai instances. Aggregate 22 GB VRAM across three physical machines.",
    )
    story.append(P(
        "HOST-A and HOST-C share a public IP. That was investigated rather than assumed: "
        "their hardware identifiers differ (different motherboards, different kernels), so "
        "they are separate virtual machines — but their measured round-trip time is "
        "<b>0.5 ms</b>, meaning they sit on the same physical host or rack. HOST-B is "
        "genuinely remote at ~310 ms."
    ))
    story += table(
        [["Link", "RTT p50", "Bulk 8 KiB round trip", "Verdict"],
         ["A ↔ C", "0.5 ms", "~1 ms", "datacenter-class"],
         ["A ↔ B", "311 ms", "354 ms (1 round trip)", "internet-class"],
         ["B ↔ C", "309 ms", "—", "internet-class"]],
        [0.9, 0.9, 1.8, 1.4],
        "All six directional paths measured; no packet loss across 360 probes.",
    )

    # ── 3. What was built ─────────────────────────────────────────────────
    story += section("What was built")
    story.append(P(
        "A distributed system in the shape the architecture demanded after measurement, "
        "not the shape it started with."
    ))
    for item in [
        "<b>Control plane</b> — FastAPI coordinator with node registration, a live "
        "resource registry with snapshot persistence, measured-topology ingest, and an "
        "Execution Intelligence planner that computes cost per million tokens and is "
        "allowed to refuse a configuration.",
        "<b>Network characterisation</b> — a benchmark that measures every node pair in "
        "both directions: RTT percentiles, jitter, packet loss, single- and multi-stream "
        "TCP throughput, connection stability.",
        "<b>Local weight loading</b> — each host reads only its assigned layer range "
        "from its own copy of the GGUF file, dequantising Q6_K, Q8_0 and F32 tensors and "
        "validating every tensor shape against the model geometry.",
        "<b>A model execution engine</b> — a Phi-mini-MoE forward pass implemented in "
        "PyTorch: RMSNorm with bias, GQA attention with RoPE, causal masking, top-2 MoE "
        "routing and per-stage KV cache.",
        "<b>An activation transport</b> — persistent TCP with length-prefixed framing, "
        "CRC32 integrity, sequence positions and direct response routing.",
        "<b>A safety layer</b> — a process registry that records every experiment "
        "process by exact PID and refuses to terminate anything it did not start.",
    ]:
        story.append(bullet(item))

    story.append(Spacer(1, 6))
    story.append(callout(
        "Why not llama.cpp's RPC, which does this already",
        "llama.cpp's RPC backend was tried first and abandoned on evidence: it ships model "
        "tensors over the network at load time. A 2 GiB shard needs ~50 s over the fast link "
        "but ~5.7 hours over the 310 ms link, and it hangs entirely on high-latency paths. "
        "The fix — load weights locally, send only activations — is what MESHWEAVE implements.",
        "accent",
    ))

    # ── 4. The measurement record ─────────────────────────────────────────
    story += section("The measurement record")
    story.append(P(
        "Every figure below was measured on the real hosts. Nothing is estimated unless "
        "labelled. The progression is the story: each step removed a cost that did not "
        "need to exist."
    ))
    story += table(
        [["Configuration", "Prefill", "Decode", "What changed"],
         ["Relay (A→B→C→B→A)", "22,018 ms", "2,663 ms/token", "baseline"],
         ["Direct return", "6,003 ms", "1,276 ms/token", "logits go straight to client"],
         ["Direct + fire-and-forget", "2,749 ms", "453 ms/token", "removed a needless ack"]],
        [1.5, 0.85, 1.05, 1.7],
        "Identical output in all three configurations. 5.9× decode improvement from two transport fixes.",
    )
    story.append(P(
        "The second fix is worth naming because it was a self-inflicted cost: the pipeline "
        "was sending a completion acknowledgement back up the chain and blocking on it, "
        "even though the client was already receiving logits on a separate channel. That "
        "acknowledgement consumed a full return traversal — ~620 ms of pure waiting per token."
    ))

    story += table(
        [["Component", "Time per token", "Share"],
         ["GPU compute, all three stages", "~66 ms", "2.6 %"],
         ["Two WAN hops (one-way each)", "~310 ms", "48 %"],
         ["Residual transport overhead", "~77 ms", "—"]],
        [2.2, 1.0, 0.8],
        "Compute is not the bottleneck and never was. Optimising it further would save milliseconds.",
    )

    # ── 5. Capacity: the claim and its limit ──────────────────────────────
    story += section("Distributed capacity — the claim, and its limit")
    story.append(P(
        "Phase 4 asked whether a model can be executed that no individual GPU can hold. "
        "The test: Phi-mini-MoE at Q8_0, 7,576 MiB of weights."
    ))
    story += table(
        [["Host", "GPU", "Free VRAM", "Model needs", "Can hold it alone?"],
         ["HOST-A", "GTX 1660 Super", "5,747 MiB", "7,576 MiB", "no — short 1,829 MiB"],
         ["HOST-B", "Quadro RTX 4000", "7,686 MiB", "7,576 MiB", "no — OOM on KV cache"],
         ["HOST-C", "RTX 2070 Super", "7,786 MiB", "7,576 MiB", "no — same"]],
        [0.8, 1.35, 0.9, 0.9, 1.8],
        "Controlled load attempts, not arithmetic. HOST-B loaded the weights and then failed to allocate the 512 MiB KV cache.",
    )
    story.append(P(
        "The claim holds, and more sharply than expected: it is not merely that the weights "
        "do not fit, but that the model's <i>working set</i> — weights plus KV cache — exceeds "
        "the largest GPU. No individual GPU in the fleet can host this model GPU-resident."
    ))
    story.append(Spacer(1, 4))
    story.append(callout(
        "But the claim has an exact boundary",
        "It is true that the model cannot be <b>GPU-resident</b> on one GPU. It is not true "
        "that it cannot run on one machine. Each host has 15-62 GB of system RAM, so CPU "
        "offloading runs it comfortably — and, as measured, far faster than distributing it.",
        "warn",
    ))

    # ── 6. The comparison that settles it ────────────────────────────────
    story += section("The comparison that settles the question")
    story.append(P(
        "Same model file, same prompt, same greedy decoding, measured on the same hardware."
    ))
    story += table(
        [["Configuration", "Tokens / second", "Basis"],
         ["Single GPU, smaller model (Q6_K on RTX 2070S)", "133.7", "model fits VRAM"],
         ["Single machine, CPU offload (Q8_0, 2 layers in RAM)", "58.0", "weights + KV exceed GPU"],
         ["Single GPU, quantised to fit", "~130", "supported alternative"],
         ["Three-host distributed (Q6_K)", "2.2", "453 ms per token"]],
        [3.0, 1.1, 1.3],
        "CPU offload measured warm on the smallest host (15 GB RAM) and still 26× faster than distribution.",
    )
    story.append(P(
        "The reason is structural, not an implementation defect. Two WAN hops at ~310 ms "
        "each add roughly 620 ms to every token; no transport optimisation removes a "
        "physical round trip across a continent. Meanwhile offloading two of thirty-two "
        "layers to RAM costs almost nothing, because these hosts have far more RAM than VRAM."
    ))

    # ── 7. What this means ───────────────────────────────────────────────
    story += section("Conclusions")
    story += table(
        [["Question", "Answer"],
         ["Can independent GPUs execute one model together?",
          "<b>Yes.</b> Proven end to end with numerical parity."],
         ["Can they run a model no single GPU can hold?",
          "<b>Yes</b> — capacity is real and demonstrated."],
         ["Is it faster than simpler alternatives?",
          "<b>No.</b> 26× slower than CPU offload, ~200× slower than one GPU."],
         ["Where would it win?",
          "Links under ~2 ms, or models exceeding single-machine RAM."]],
        [2.3, 3.5],
    )
    story.append(Spacer(1, 6))
    story.append(P(
        "The distributed path is a <b>capacity mechanism</b>, not a latency one. On this "
        "fleet it is the wrong tool: 22 GB of VRAM across three machines is less useful "
        "than 15-62 GB of RAM on any one of them, and the network costs 300 ms for the "
        "privilege of crossing between them."
    ))
    story.append(P(
        "The one configuration still worth testing is a two-node split between HOST-A and "
        "HOST-C, whose link measures 0.5 ms rather than 310 ms. That would pay roughly 1 ms "
        "of network per token instead of 450 ms, and could plausibly compete with the "
        "58 tok/s offload baseline. If it cannot, the definitive finding is that this fleet "
        "cannot benefit from distribution at all — which is worth establishing rather than "
        "inferring."
    ))

    # ── 8. Engineering notes ─────────────────────────────────────────────
    story += section("Engineering notes")
    story.append(P(
        "Several defects were found by measurement rather than inspection. They are recorded "
        "because each cost real time and each is easy to repeat."
    ))
    story += table(
        [["Defect", "Symptom", "Cause"],
         ["Position advancing per stage", "cosine 0.99998 but mean error 3.26",
          "each stage rotated RoPE from its own offset instead of the absolute start"],
         ["`reply_to` not propagated", "direct return silently fell back to relay",
          "upstream stages built a fresh header and dropped the field"],
         ["Blocking on a downstream ack", "+620 ms per token",
          "client already had the result on another channel"],
         ["MoE routing sync", "30 ms/token for 11 layers",
          "`torch.unique().tolist()` forced ~64 GPU syncs per token"]],
        [1.6, 1.9, 2.4],
    )
    story.append(Spacer(1, 5))
    story.append(P(
        "One methodological correction is worth stating plainly: two phases of debugging were "
        "spent chasing a numerical mismatch that did not exist. The output was compared "
        "against <i>rendered text</i> from llama.cpp instead of against its logits vector. "
        "Recording the reference logits — a 32,064-float file — settled it in a single "
        "comparison and showed the implementation had been correct all along."
    ))

    # ── 9. Operating constraints ─────────────────────────────────────────
    story += section("Safety and operational record")
    story.append(P(
        "One incident shaped the operating rules for everything after it: an early cleanup "
        "routine extracted every listening PID from <i>ss</i> output and terminated them, "
        "which killed sshd on all three hosts. The fix was not a better cleanup function but "
        "the removal of the capability — a process registry now records every experiment "
        "process by exact PID, and termination is refused for anything it did not start. "
        "Twenty-nine tests enforce this, including a static scan for forbidden patterns."
    ))
    story.append(P(
        "When two hosts later became unavailable because of GPU allocations outside the "
        "container's PID namespace, the correct action was to stop and report rather than "
        "work around the rule. That is recorded in the Phase 4.1 report."
    ))

    # ── 10. Status ───────────────────────────────────────────────────────
    story += section("Status at handoff")
    story += table(
        [["Item", "State"],
         ["Repository", "151 files, 111 tests passing, ruff and mypy --strict clean"],
         ["Checkpoint", "git tag poc-checkpoint-1"],
         ["Hosts", "HOST-B available; HOST-A and HOST-C need an instance restart"],
         ["Reproducibility", "backup/host_manifest.json — model hashes, build commands, ports"],
         ["Next experiment", "two-node A+C split at 0.5 ms link"]],
        [1.1, 4.7],
    )
    story.append(Spacer(1, 8))
    story.append(P(
        '<i>"Can we turn geographically distributed, heterogeneous, independently owned '
        'GPUs into a reliable virtual AI supercomputer?"</i>',
        "body",
    ))
    story.append(P(
        "On this evidence: they can be coordinated, and they can jointly hold a model no "
        "single card can. Whether that is worth doing depends entirely on the network "
        "between them — and at 300 ms, it is not.",
        "body",
    ))

    doc.build(story)
    print(f"body written: {path}")


if __name__ == "__main__":
    out = sys.argv[1] if len(sys.argv) > 1 else "body.pdf"
    Path(out).parent.mkdir(parents=True, exist_ok=True)
    build(out)
